function buildInventory(provenance, capture, supplement) {
  const checks = [];
  function check(name, pass, details) { checks.push({name, pass: !!pass, ...(details === undefined ? {} : {details})}); }
  const inputs = Object.keys(provenance.declared_raw_paths).sort();
  check("unique exact-date input union equals captured path set", JSON.stringify(inputs) === JSON.stringify(capture.logs.map(x=>x.path).sort()));
  check("nine manifest byte comparisons", provenance.manifests.length === 9 && provenance.manifests.every(x=>x.current_equals_committed));
  const commandGroups = new Map();
  const wrapperCommandGroups = new Map();
  const logs = capture.logs.map(raw => {
    const receipts = raw.markers;
    const headers = receipts.filter(x=>/^\[runlog\] \d{4}-/.test(x.text)).map(x=>{
      const m=x.text.match(/^\[runlog\] (\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})  name=(.+)$/);
      return {line:x.line,raw:x.text,start_kst:m ? m[1] : null,name:m ? m[2] : null};
    });
    const footers = receipts.filter(x=>x.text.startsWith("[runlog] 종료코드 ")).map(x=>{
      const m=x.text.match(/^\[runlog\] 종료코드 (-?\d+)  소요 ([\d.]+)분  \(([^)]+)\)$/);
      return {line:x.line,raw:x.text,exit_code:m ? Number(m[1]) : null,printed_elapsed_minutes:m ? Number(m[2]) : null,end_kst:m ? m[3] : null};
    });
    const wrappers = receipts.filter(x=>x.text.startsWith("[runlog] cmd=")).map(x=>({line:x.line,command:x.text.slice(13)}));
    const cwd = receipts.filter(x=>x.text.startsWith("[runlog] cwd=")).map(x=>({line:x.line,cwd:x.text.slice(13)}));
    for(const x of wrappers) {
      const g=wrapperCommandGroups.get(x.command)||{command:x.command,occurrences:[]};
      g.occurrences.push({path:raw.path,line:x.line}); wrapperCommandGroups.set(x.command,g);
    }
    const phases=[];
    const anomalies=[];
    let active=null;
    for(const item of receipts) {
      if(item.text.startsWith("[PHASE_BEGIN] ")) {
        const m=item.text.match(/^\[PHASE_BEGIN\] (\d+)\/(\d+) ([^;]+);/);
        if(!m || active) anomalies.push({line:item.line,reason:"malformed/nested phase begin",text:item.text});
        active={ordinal:m ? Number(m[1]) : null,total:m ? Number(m[2]) : null,phase:m ? m[3] : null,begin_line:item.line,begin_raw:item.text,commands:[]};
        phases.push(active);
      } else if(item.text.startsWith("[PHASE_COMMAND] ")) {
        if(!active) anomalies.push({line:item.line,reason:"command outside phase",text:item.text});
        else active.commands.push({line:item.line,argv:JSON.parse(item.text.slice(16)),source:"literal PHASE_COMMAND receipt"});
      } else if(item.text.startsWith("[PHASE_END] ")) {
        const m=item.text.match(/^\[PHASE_END\] (\d+)\/(\d+) ([^;]+); rc=(-?\d+); status=(.+)$/);
        if(!m || !active || active.ordinal!==Number(m[1]) || active.total!==Number(m[2]) || active.phase!==m[3])
          anomalies.push({line:item.line,reason:"unmatched phase end",text:item.text});
        if(active) Object.assign(active,{end_line:item.line,end_raw:item.text,exit_code:m ? Number(m[4]) : null,status:m ? m[5] : null});
        active=null;
      }
    }
    if(active) anomalies.push({line:active.begin_line,reason:"missing phase end"});
    const declarations = raw.path.includes("Stage4eqW_public_qa_supply_cpu_") ? supplement.public_qa_phase_declarations : [];
    for(const p of phases) {
      if(p.commands.length===0 && declarations.length===1) {
        const matched=declarations[0].phases.filter(x=>x[0]===p.phase);
        if(matched.length===1) p.commands.push({line:declarations[0].line,argv:matched[0][1],source:"phase argv declaration inside PUBLIC_QA_SUPPLY_CHECK_ONLY output; no PHASE_COMMAND echo for this phase"});
      }
      p.complete = Number.isInteger(p.end_line);
      p.successful = p.complete && p.exit_code===0 && p.status==="PASS";
      for(const c of p.commands) {
        const key=JSON.stringify(c.argv);
        const g=commandGroups.get(key)||{argv:c.argv,occurrences:[]};
        g.occurrences.push({path:raw.path,phase:p.phase,line:c.line,source:c.source});
        commandGroups.set(key,g);
      }
    }
    const finals=receipts.filter(x=>x.text.startsWith("[EXPERIMENT_FINAL] ")).map(x=>({line:x.line,raw:x.text,receipt:JSON.parse(x.text.slice(19))}));
    const final=finals.length===1 ? finals[0].receipt : null;
    const lastFooter=footers.length===1 ? footers[0] : null;
    const isPipeline=phases.length>0;
    const phaseNames=phases.map(x=>x.phase);
    const canonicalNames=["REGRESSION","PREFLIGHT","EXECUTE"];
    const footerClosed=headers.length===1 && wrappers.length===1 && footers.length===1 && lastFooter.exit_code!==null && headers[0].line<lastFooter.line;
    const pipelineComplete=isPipeline && anomalies.length===0 && JSON.stringify(phaseNames)===JSON.stringify(canonicalNames)
      && phases.every((p,i)=>p.ordinal===i+1 && p.total===3 && p.successful && p.commands.length===1)
      && finals.length===1 && final.status==="COMPLETE" && final.returncode===0 && final.main_experiment_invoked===true && final.failed_phase===null
      && JSON.stringify(final.phases)===JSON.stringify(phases.map(p=>({phase:p.phase,returncode:p.exit_code,status:p.status})))
      && footerClosed && lastFooter.exit_code===0 && phases[2].end_line<finals[0].line && finals[0].line<lastFooter.line;
    const directRegression=!isPipeline && wrappers.length===1 && wrappers[0].command.includes(" -m unittest ");
    const noPhaseException=!isPipeline && lastFooter && lastFooter.exit_code!==0;
    const status=pipelineComplete ? "CLOSED_COMPLETE_THREE_PHASE_EXECUTION" :
      directRegression && footerClosed && lastFooter.exit_code===0 ? "CLOSED_SUCCESSFUL_STANDALONE_REGRESSION_ONLY" :
      noPhaseException && footerClosed ? "CLOSED_FAILED_BEFORE_ANY_PHASE_RECEIPT" :
      !footerClosed ? "INCOMPLETE_OR_MISSING_RUNLOG_FOOTER" : "UNRESOLVED_RECEIPT_COMBINATION";
    const execute=phases.find(x=>x.phase==="EXECUTE");
    const executeArgv=execute?.commands.length===1 ? execute.commands[0].argv : null;
    const modeIndex=executeArgv ? executeArgv.indexOf("--mode") : -1;
    const mode=modeIndex>=0 ? executeArgv[modeIndex+1] : null;
    const unitSummaries=raw.diagnostics.filter(x=>/^Ran \d+ tests? in /.test(x.text)).map(x=>{
      const m=x.text.match(/^Ran (\d+) tests? in ([\d.]+)s$/);
      return {line:x.line,raw:x.text,tests:m?Number(m[1]):null,seconds:m?Number(m[2]):null};
    });
    check(raw.path+" current bytes equal committed blob",raw.committed_objects.every(x=>x.current_equals_committed));
    check(raw.path+" explicit manifest hashes/bytes where supplied",raw.committed_objects.every(x=>x.manifest_bytes_match!==false && x.manifest_sha256_match!==false));
    check(raw.path+" exactly one dated header and footer",footerClosed && headers[0].start_kst?.startsWith("2026-10-19 ") && lastFooter.end_kst?.startsWith("2026-10-19 "));
    check(raw.path+" parse has no unmatched/nested phase",anomalies.length===0);
    if(isPipeline) check(raw.path+" complete phase/final/footer agreement",pipelineComplete);
    return {
      path:raw.path,basename:raw.path.split("/").at(-1),date_from_declared_filename:"20261019",
      source_manifest_paths:raw.source_manifest_paths,provenance:provenance.declared_raw_paths[raw.path],
      bytes:raw.bytes,sha256:raw.sha256,line_count:raw.line_count,ends_with_lf:raw.ends_with_lf,
      committed_objects:raw.committed_objects,runlog_headers:headers,runlog_cwd:cwd,runlog_commands:wrappers,runlog_footers:footers,
      wrapper_completed:footerClosed,wrapper_exit_codes:footers.map(x=>x.exit_code),
      execution_status:status,three_phase_completed:pipelineComplete,
      standalone_regression_only:directRegression,no_phase_receipt_exception:noPhaseException,
      execute_command_mode:mode,execute_command_argv:executeArgv,
      phases,experiment_final_receipts:finals,regression_summaries:unitSummaries,
      diagnostic_lines:raw.diagnostics,parse_anomalies:anomalies,
      raw_receipt_lines:receipts,
      limitations:raw.path.includes("Stage4eqW_public_qa_supply_cpu_") ?
        ["Three phase begin/end and final receipts are present, but there are no literal PHASE_COMMAND lines. Phase argv is preserved as the preflight output's declaration, not relabeled as a separate command echo."] : []
    };
  });
  function counts(values){const d={};for(const v of values)d[String(v)]=(d[String(v)]||0)+1;return d;}
  const summaries={
    manifests:provenance.manifests.length,
    declared_raw_txt_paths_all_filename_dates:inputs.length+provenance.non_20261019_not_read.length,
    date20261019_input_logs:inputs.length,unique_input_logs:inputs.length,
    date20261019_total_current_bytes:logs.reduce((s,x)=>s+x.bytes,0),
    filename_number_counts:counts(logs.map(x=>x.basename.split("_")[0])),
    current_committed_blob_matches:logs.filter(x=>x.committed_objects.every(y=>y.current_equals_committed)).length,
    logs_with_explicit_per_file_manifest_hash:logs.filter(x=>x.committed_objects.some(y=>y.manifest_sha256_match!==null)).length,
    logs_without_explicit_per_file_manifest_hash:logs.filter(x=>x.committed_objects.every(y=>y.manifest_sha256_match===null)).length,
    explicit_per_file_manifest_hash_mismatches:logs.filter(x=>x.committed_objects.some(y=>y.manifest_sha256_match===false || y.manifest_bytes_match===false)).length,
    wrapper_completed:logs.filter(x=>x.wrapper_completed).length,
    wrapper_exit_code_counts:counts(logs.flatMap(x=>x.wrapper_exit_codes)),
    missing_or_ambiguous_footer_logs:logs.filter(x=>!x.wrapper_completed).map(x=>x.path),
    three_phase_complete_logs:logs.filter(x=>x.three_phase_completed).length,
    phase_execution_receipts:logs.reduce((s,x)=>s+x.phases.length,0),
    phase_name_counts:counts(logs.flatMap(x=>x.phases.map(p=>p.phase))),
    literal_phase_command_echoes:logs.reduce((s,x)=>s+x.phases.reduce((t,p)=>t+p.commands.filter(c=>c.source==="literal PHASE_COMMAND receipt").length,0),0),
    phase_argv_from_preflight_declaration_not_echo:logs.reduce((s,x)=>s+x.phases.reduce((t,p)=>t+p.commands.filter(c=>c.source!=="literal PHASE_COMMAND receipt").length,0),0),
    top_level_runlog_command_headers:logs.reduce((s,x)=>s+x.runlog_commands.length,0),
    standalone_successful_regression_only:logs.filter(x=>x.standalone_regression_only && x.wrapper_exit_codes[0]===0).length,
    failed_before_any_phase_receipt:logs.filter(x=>x.no_phase_receipt_exception).length,
    completed_execute_mode_counts:counts(logs.filter(x=>x.three_phase_completed).map(x=>x.execute_command_mode)),
    multiple_top_level_headers_or_commands:logs.filter(x=>x.runlog_headers.length!==1 || x.runlog_commands.length!==1).map(x=>x.path),
    repeated_phase_command_argv_groups:Array.from(commandGroups.values()).filter(g=>g.occurrences.length>1).length,
    repeated_top_level_command_groups:Array.from(wrapperCommandGroups.values()).filter(g=>g.occurrences.length>1).length,
    parse_check_count:checks.length,parse_check_failures:checks.filter(x=>!x.pass).length
  };
  return {input_logs:inputs,manifests:provenance.manifests,declared_paths_provenance:provenance.declared_raw_paths,
    declared_other_date_logs_not_read:provenance.non_20261019_not_read,
    summary:summaries,logs,checks,
    repeated_phase_command_argv:Array.from(commandGroups.values()).filter(g=>g.occurrences.length>1),
    repeated_top_level_commands:Array.from(wrapperCommandGroups.values()).filter(g=>g.occurrences.length>1)};
}
